package kernels

import "os"

// riscv64 RVV kernels generated by go-asmgen (sum_riscv64.s); the GEMM
// micro-kernel is in gemm_riscv64.go. The vector
// extension is optional on RISC-V, so each wrapper uses the kernel only when
// the kernel reports V in AT_HWCAP, and runs the scalar oracle otherwise. The
// loops are vector-length agnostic: they run on any VLEN.
//
//go:generate sh -c "cd asmgen/riscv64 && go run . && mv sum_riscv64.s ../../sum_riscv64.s"
//
// max/min stay on the scalar reducers: RVV's vfmax/vfmin follow IEEE 754-2019
// maximumNumber, which returns the number when the other operand is a NaN,
// where NumPy and Go's max propagate the NaN.

// HaveReduceSIMD reports that this build ships SIMD kernels; they run when
// useRVV is true.
const HaveReduceSIMD = true

// hwcapV is COMPAT_HWCAP_ISA_V, the bit of 'V' in the letter-indexed riscv
// AT_HWCAP (Linux arch/riscv/include/asm/hwcap.h: 1 << ('V' - 'A')). The kernel
// sets it only when it also saves vector state across context switches.
const hwcapV = 1 << ('V' - 'A')

// useRVV selects the RVV kernels. A var so tests can force the scalar path on
// hardware that has V (never the reverse: that would fault).
var useRVV = rvvFromAuxv()

func rvvFromAuxv() bool {
	auxv, err := os.ReadFile("/proc/self/auxv")
	return err == nil && hwcapFrom(auxv)&hwcapV != 0
}

// The sum is floats.SumPairwise on every target (reduce_sum.go): NumPy's order
// (the former sumRVV regrouped [MaxInt64, MinInt64, -3] as float64 on a real
// SpacemiT X60: the mean was 0, NumPy's -1; SumPairwise adds n < 8 left to right
// as NumPy does). The elementwise kernels and sqrt are go-simd/floats'
// (reduce_floats_elem.go).

// maxSIMD / minSIMD are the NaN-propagating extrema of a (non-empty): the RVV
// kernels (vfmax/vfmin with a vmfne NaN count) when the CPU reports V, the
// four-chain scalar reducers otherwise.
func maxSIMD(a []float64) float64 {
	if !useRVV {
		return maxUnrolled(a)
	}
	return maxRVV(&a[0], len(a))
}

func minSIMD(a []float64) float64 {
	if !useRVV {
		return minUnrolled(a)
	}
	return minRVV(&a[0], len(a))
}

//go:noescape
func maxRVV(a *float64, n int) float64

//go:noescape
func minRVV(a *float64, n int) float64

// dotSIMD is the inner product (RVV kernel, one fused accumulator per lane).
func dotSIMD(a, b []float64) float64 {
	if !useRVV || len(a) == 0 {
		return dotRange(a, b)
	}
	_ = b[len(a)-1] // the kernel reads len(a) of b
	return dotRVV(&a[0], &b[0], len(a))
}

//go:noescape
func dotRVV(a, b *float64, n int) float64
